style.css:
/* Dark Sakura */
body { background: #19151D !important; color: #F0DFEB !important; }
h1, h2, h3 { color: #DCA5C7 !important; }
p { color: #C5AEC2 !important; }
a { color: #E6ACD0 !important; }
button {
  background: #68465F !important;
  color: #FFF0F8 !important;
  border: 1px solid #A9799D !important;
  border-radius: 15px !important;
}
input, textarea {
  background: #29212E !important;
  color: #F0DFEB !important;
  border: 1px solid #765A78 !important;
}
::selection { background: #A9799D; color: white; }
